public class MathUtils_mulAndCheck_TriageGen0Test {













    @Test
    public void testNegativeByNegative_Overflow() {
        try {
            // a = -2, b = Long.MIN_VALUE/(-2) -> this might work, 
            // let's use values that exceed MAX_VALUE
            // If a = -1, b = Long.MIN_VALUE, ret = Long.MIN_VALUE (valid)
            // If a = -2, b = Long.MIN_VALUE / -2 + 1 (overflows)
            MathUtils.mulAndCheck(-1000000000000000000L, -1000000000000000000L);
            org.junit.Assert.fail("Expected ArithmeticException");
        } catch (ArithmeticException e) {
            assertEquals("overflow: multiply", e.getMessage());
        }
    }




