package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class MathUtils_mulAndCheck_TriageGen0Test {















    @Test
    public void testBoundaryCases() {
        // Test MAX_VALUE
        assertEquals(Long.MAX_VALUE, MathUtils.mulAndCheck(1L, Long.MAX_VALUE));

        // Test MIN_VALUE
        assertEquals(Long.MIN_VALUE, MathUtils.mulAndCheck(1L, Long.MIN_VALUE));
        assertEquals(Long.MIN_VALUE, MathUtils.mulAndCheck(-1L, Long.MAX_VALUE == Long.MIN_VALUE ? 1L : (Long.MIN_VALUE / -1L == Long.MIN_VALUE ? Long.MIN_VALUE : 1L))); 
        // Note: Long.MIN_VALUE / -1 is actually Long.MIN_VALUE due to overflow, 
        // but the logic handles it via the division check.

        // Specifically target the (a < 0 && b < 0) branch with overflow
        try {
            MathUtils.mulAndCheck(Long.MIN_VALUE, -1L);
            // Long.MIN_VALUE / -1 results in Long.MIN_VALUE (overflow)
            // In the code: if (a >= Long.MAX_VALUE / b) -> if (MIN >= MAX / -1) -> if (MIN >= -MAX) -> False.
            // Wait, if a = -1, b = Long.MIN_VALUE, then a < b is true (symmetry triggers)
            // Let's use a = Long.MIN_VALUE, b = -1. 
            // a < 0 and b < 0. a >= Long.MAX_VALUE / b => Long.MIN_VALUE >= -Long.MAX_VALUE.
            // Long.MAX_VALUE is 2^63-1. -Long.MAX_VALUE is -2^63+1.
            // Long.MIN_VALUE is -2^63. 
            // -2^63 >= -2^63 + 1 is FALSE. So it throws.
            MathUtils.mulAndCheck(Long.MIN_VALUE, -1L);
        } catch (ArithmeticException e) {
            assertEquals("overflow: multiply", e.getMessage());
        }
    }


}

